<?php
declare(strict_types=1);requireRole('social-service-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='process-return';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();$userId=(int)$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$distributionId=filter_input(INPUT_POST,'distribution_id',FILTER_VALIDATE_INT);$quantity=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);$condition=(string)($_POST['condition']??'');$restore=(string)($_POST['restore_to']??'');if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$distributionId||!$quantity||$quantity<1||!in_array($condition,['good','damaged','unusable'],true)||!in_array($restore,['officer-pool','central-stock','removed'],true))$errors[]='Complete all return details.';if($condition!=='good'&&$restore!=='removed')$errors[]='Damaged or unusable items must be removed from reusable stock.';if($condition==='good'&&$restore==='removed')$errors[]='A good item must be restored to a stock location.';if(!$errors){try{$db->beginTransaction();$stmt=$db->prepare('SELECT d.*,(SELECT COALESCE(SUM(r.quantity),0) FROM item_returns r WHERE r.distribution_id=d.id) returned FROM distributions d WHERE d.id=:id AND d.distributed_by=:user FOR UPDATE');$stmt->execute(['id'=>$distributionId,'user'=>$userId]);$distribution=$stmt->fetch();if(!$distribution)throw new RuntimeException('Distribution record was not found in your issue history.');$available=(int)$distribution['quantity']-(int)$distribution['returned'];if($quantity>$available)throw new RuntimeException("Return exceeds the outstanding issued quantity. Available: $available.");$reusable=$condition==='good'?1:0;$insert=$db->prepare('INSERT INTO item_returns(distribution_id,quantity,item_condition,reusable,restore_to,processed_by) VALUES(:distribution,:quantity,:condition,:reusable,:restore,:user)');$insert->execute(['distribution'=>$distributionId,'quantity'=>$quantity,'condition'=>$condition,'reusable'=>$reusable,'restore'=>$restore,'user'=>$userId]);$id=(int)$db->lastInsertId();if($restore==='officer-pool'){$db->prepare('UPDATE officer_pools SET reused=reused+:quantity WHERE officer_id=:user AND item_id=:item')->execute(['quantity'=>$quantity,'user'=>$userId,'item'=>$distribution['item_id']]);}elseif($restore==='central-stock'){$db->prepare('UPDATE inventory_items SET quantity=quantity+:quantity WHERE id=:item')->execute(['quantity'=>$quantity,'item'=>$distribution['item_id']]);}$db->commit();logActivity('Returns','Processed distributed item return','RET-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),$restore);$_SESSION['flash_success']='Return processed and stock destination updated.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=process-return');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to process return.';}}}
try{$issued=$db->prepare('SELECT d.id,d.quantity-(SELECT COALESCE(SUM(r.quantity),0) FROM item_returns r WHERE r.distribution_id=d.id) returnable,b.full_name,b.nic,i.item_name,i.variety FROM distributions d JOIN beneficiaries b ON b.id=d.beneficiary_id JOIN inventory_items i ON i.id=d.item_id WHERE d.distributed_by=:user HAVING returnable>0 ORDER BY d.id DESC');$issued->execute(['user'=>$userId]);$issued=$issued->fetchAll();$returns=$db->prepare('SELECT r.*,b.full_name,i.item_name,i.variety FROM item_returns r JOIN distributions d ON d.id=r.distribution_id JOIN beneficiaries b ON b.id=d.beneficiary_id JOIN inventory_items i ON i.id=d.item_id WHERE r.processed_by=:user ORDER BY r.id DESC LIMIT 50');$returns->execute(['user'=>$userId]);$returns=$returns->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$issued=$returns=[];$errors[]='Return workflow is unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Return Management | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body class="return-page-body"><?php require __DIR__.'/../../includes/social-service-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Return Management</h1></div></header><main class="dashboard-content return-management-page"><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="return-card"><div class="return-card-header"><h2>Process Return</h2></div><form method="post" class="return-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><div class="return-form-grid"><label>Distribution Record<select name="distribution_id" required><option value="">Select issued item</option><?php foreach($issued as $r):?><option value="<?=(int)$r['id']?>">DIST-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?> — <?=htmlspecialchars($r['full_name'].' — '.$r['item_name'].' ('.$r['returnable'].' outstanding)',ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" min="1" value="1" required></label><label>Condition<select name="condition" required><option value="">Select condition</option><option value="good">Good</option><option value="damaged">Damaged</option><option value="unusable">Unusable</option></select></label><label>Restore To<select name="restore_to" required><option value="">Select destination</option><option value="officer-pool">My Officer Pool</option><option value="central-stock">Central Stock</option><option value="removed">Removed / Disposal</option></select></label></div><button class="process-return-button">Process Return</button></form></section><section class="return-card recent-returns-card"><div class="return-card-header"><h2>Recent Returns</h2></div><div class="return-table-wrap"><table class="return-table"><thead><tr><th>Return ID</th><th>Beneficiary</th><th>Item</th><th>Condition</th><th>Reusable</th><th>Restored To</th><th>Date</th></tr></thead><tbody><?php if(!$returns):?><tr><td colspan="7" class="return-empty">No returns recorded yet.</td></tr><?php else:foreach($returns as $r):?><tr><td>RET-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?> × <?=(int)$r['quantity']?></td><td><?=ucfirst($r['item_condition'])?></td><td><?=$r['reusable']?'Yes':'No'?></td><td><?=ucwords(str_replace('-',' ',$r['restore_to']))?></td><td><?=date('d M Y',strtotime($r['processed_at']))?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
